      // wing
      [[198, 92], [212, 108], [226, 120], [240, 124], [254, 122], [268, 112]].forEach(([a, l]) => { const F = frm(160, 132, 1, a); s += Pm(F, `M0 -8C${l * 0.4} -17 ${l * 0.75} -14 ${l} 6C${l * 0.7} 13 ${l * 0.35} 16 0 8Z`) + Pm(F, `M${l * 0.56} -1C${l * 0.66} -8 ${l * 0.84} -6 ${l * 0.92} 4C${l * 0.8} 8 ${l * 0.64} 7 ${l * 0.56} -1Z`); });
      [205, 222, 239, 256, 271].forEach(a => s += Pm(frm(160, 132, 1, a), 'M0 -8C26 -15 54 -13 74 4C52 13 26 15 0 8Z'));
      [212, 234, 256, 276].forEach(a => s += Pm(frm(160, 132, 1, a), 'M0 -10C12 -16 34 -16 46 0C34 16 12 16 0 10Z'));
      // body, breast scales, neck, head
