      [[214, 34], [238, 38], [262, 36]].forEach(([a, l]) => s += Pm(frm(232, 64, 1, a), `M0 -4C10 -9 ${l - 10} -12 ${l} -6C${l + 6} -1 ${l + 2} 8 ${l - 6} 8C${l - 16} 8 8 5 0 4Z`));
