    const B = (x, y, w, h, r) => `<rect ${R} x="${n1(x)}" y="${n1(y)}" width="${n1(w)}" height="${n1(h)}"${r ? ` rx="${r}"` : ''}/>`;
    const ln = d => `<path d="${d}" ${T}/>`;
    const dot = (x, y, r) => `<circle cx="${n1(x)}" cy="${n1(y)}" r="${r}" fill="${INK}"/>`;
