    const star = (x, y, r, n = 5) => Q(starP(x, y, r, r * .58, n));
    const spk = (x, y, r) => `<path d="${pd(starP(x, y, r, r * .3, 4))}" fill="${INK}"/>`;
    const arcP = (cx, cy, rx, ry, a0, a1, n = 12) => { const a = []; for (let i = 0; i <= n; i++) { const t = rad(a0 + (a1 - a0) * i / n); a.push([cx + rx * cos(t), cy + ry * sin(t)]); } return a; };
    const ell = (cx, cy, rx, ry, n = 40) => arcP(cx, cy, rx, ry, 0, 360 - 360 / n, n - 1);
    const rot = (a, cx, cy, d) => { const c = cos(rad(d)), s = sin(rad(d)); return a.map(([x, y]) => [cx + (x - cx) * c - (y - cy) * s, cy + (x - cx) * s + (y - cy) * c]); };
    const sector = (cx, cy, rx0, ry0, rx1, ry1, a0, a1, n = 8) => [...arcP(cx, cy, rx1, ry1, a0, a1, n), ...arcP(cx, cy, rx0, ry0, a1, a0, n)];
    const ringS = (cx, cy, rx0, ry0, rx1, ry1, n, a0 = 0) => rep(n, i => Q(sector(cx, cy, rx0, ry0, rx1, ry1, a0 + i * 360 / n, a0 + (i + 1) * 360 / n, 6)));
    // keep the part of a polygon where a*x + b*y <= c
    const clip = (poly, a, b, c) => { const o = []; for (let i = 0; i < poly.length; i++) { const p = poly[i], q = poly[(i + 1) % poly.length], dp = a * p[0] + b * p[1] - c, dq = a * q[0] + b * q[1] - c; if (dp <= 0) o.push(p); if (dp * dq < 0) { const t = dp / (dp - dq); o.push([p[0] + t * (q[0] - p[0]), p[1] + t * (q[1] - p[1])]); } } return o; };
    // cut a convex polygon into bands; ang = direction across the bands (deg); fr = cut fractions or a band count
    const cut = (poly, ang, fr) => { const a = cos(rad(ang)), b = sin(rad(ang)), pr = poly.map(p => a * p[0] + b * p[1]), lo = Math.min(...pr), hi = Math.max(...pr); if (typeof fr === 'number') { const n = fr; fr = []; for (let i = 1; i < n; i++) fr.push(i / n); } const k = [0, ...fr, 1].map(f => lo + (hi - lo) * f), o = []; for (let i = 0; i + 1 < k.length; i++) o.push(clip(clip(poly, a, b, k[i + 1]), -a, -b, -k[i])); return o; };
    const bands = (poly, ang, fr) => cut(poly, ang, fr).map(Q).join('');
    const qp = (x0, y0, cx, cy, x1, y1, n = 10) => { const a = []; for (let i = 0; i <= n; i++) { const t = i / n, u = 1 - t; a.push([u * u * x0 + 2 * u * t * cx + t * t * x1, u * u * y0 + 2 * u * t * cy + t * t * y1]); } return a; };
    const tube = (x0, y0, x1, y1, w0, w1 = w0) => { const dx = x1 - x0, dy = y1 - y0, l = Math.hypot(dx, dy), nx = -dy / l, ny = dx / l, h0 = w0 / 2, h1 = w1 / 2, p = (x, y) => n1(x) + ' ' + n1(y); return P(`M${p(x0 + nx * h0, y0 + ny * h0)}L${p(x1 + nx * h1, y1 + ny * h1)}A${n1(h1)} ${n1(h1)} 0 0 0 ${p(x1 - nx * h1, y1 - ny * h1)}L${p(x0 - nx * h0, y0 - ny * h0)}A${n1(h0)} ${n1(h0)} 0 0 0 ${p(x0 + nx * h0, y0 + ny * h0)}Z`); };
    const heart = (x, y, s) => P(`M${n1(x)} ${n1(y + s)}C${n1(x - s * 1.7)} ${n1(y)} ${n1(x - s * .7)} ${n1(y - s * 1.3)} ${n1(x)} ${n1(y - s * .4)}C${n1(x + s * .7)} ${n1(y - s * 1.3)} ${n1(x + s * 1.7)} ${n1(y)} ${n1(x)} ${n1(y + s)}Z`);
    // a leaf as two halves split by its midrib
    const leaf2 = (x0, y0, x1, y1, w) => { const dx = x1 - x0, dy = y1 - y0, l = Math.hypot(dx, dy), nx = -dy / l * w * 2, ny = dx / l * w * 2, mx = (x0 + x1) / 2, my = (y0 + y1) / 2, a = `M${n1(x0)} ${n1(y0)}Q`, b = ` ${n1(x1)} ${n1(y1)}Z`; return P(a + n1(mx + nx) + ' ' + n1(my + ny) + b) + P(a + n1(mx - nx) + ' ' + n1(my - ny) + b); };
    const cloud = (x, y, s) => P(`M${x} ${y}q${n1(-4 * s)} ${n1(-26 * s)} ${n1(22 * s)} ${n1(-28 * s)}q${n1(6 * s)} ${n1(-22 * s)} ${n1(32 * s)} ${n1(-16 * s)}q${n1(22 * s)} ${n1(-12 * s)} ${n1(34 * s)} ${n1(12 * s)}q${n1(22 * s)} ${n1(2 * s)} ${n1(18 * s)} ${n1(32 * s)}z`);
    // move + scale finished markup (coordinates only; the ink width stays the same)
    const tfd = (d, tx, ty, k) => { let c = '', i = 0; const o = []; for (const t of d.match(/[a-zA-Z]|-?\d*\.?\d+/g)) { if (/[a-zA-Z]/.test(t)) { c = t; i = 0; o.push(t); continue; } let v = +t; const up = c === c.toUpperCase(); if (c === 'A' || c === 'a') { const j = i % 7; v = j > 1 && j < 5 ? v : up && j === 5 ? tx + k * v : up && j === 6 ? ty + k * v : k * v; } else v = !up ? k * v : c === 'H' ? tx + k * v : c === 'V' ? ty + k * v : (i % 2 ? ty : tx) + k * v; o.push(n1(v)); i++; } return o.join(' '); };
    const tf = (s, tx, ty, k) => s.replace(/(?<![\w-])(cx|cy|x|y|r|rx|ry|width|height)="([-\d.]+)"/g, (m, a, v) => `${a}="${n1(a === 'cx' || a === 'x' ? tx + k * v : a === 'cy' || a === 'y' ? ty + k * v : k * v)}"`).replace(/ d="([^"]+)"/g, (m, d) => ` d="${tfd(d, tx, ty, k)}"`).replace(/rotate\(([-\d.]+) ([-\d.]+) ([-\d.]+)\)/g, (m, a, x, y) => `rotate(${a} ${n1(tx + k * x)} ${n1(ty + k * y)})`);
    const nm = (en, fr, es, de, zh) => ({ en, fr, es, de, zh });

    /* ---------- 1. music box ---------- */
    const tutu = (cx, y, w, h, n) => { let d = `M${cx - w} ${y}Q${cx} ${y - h} ${cx + w} ${y}`; const st = 2 * w / n; for (let i = 0; i < n; i++) d += `q${n1(-st / 2)} ${n1(h * .55)} ${n1(-st)} 0`; return P(d + 'Z'); };
    const note = (x, y) => ln(`M${x + 6.5} ${y - 1}V${y - 24}q7 4 9 13`) + E(x, y, 7.5, 5.5, -20);
    const musicBox = () => {
      let s = frame() + P('M8 248H292V274Q292 292 274 292H26Q8 292 8 274Z');
      s += note(30, 112) + note(44, 156) + note(254, 100) + note(270, 144);
      s += spk(38, 34, 8) + spk(262, 34, 8) + spk(30, 214, 7) + spk(274, 186, 6);
      s += P('M70 178V86Q70 46 110 46H190Q230 46 230 86V178Z') + ringS(150, 112, 46, 40, 58, 52, 10, -90) + E(150, 112, 46, 40);
      s += Q([[90, 56], [99, 68], [90, 80], [81, 68]]) + Q([[210, 56], [219, 68], [210, 80], [201, 68]]) + heart(90, 152, 9) + heart(210, 152, 9);
      s += P('M56 176L66 166H234L244 176Z') + B(56, 176, 188, 13, 3) + [70, 89, 108, 192, 211, 230].map(x => C(x, 182.5, 5.5)).join('');
      s += B(56, 189, 188, 61, 5) + B(66, 197, 50, 45, 6) + B(125, 197, 50, 45, 6) + B(184, 197, 50, 45, 6);
      s += Q([[91, 203], [104, 219.5], [91, 236], [78, 219.5]]) + C(91, 219.5, 6) + Q([[209, 203], [222, 219.5], [209, 236], [196, 219.5]]) + C(209, 219.5, 6) + heart(150, 221, 11);
      s += P('M60 250Q75 270 90 250Z') + P('M210 250Q225 270 240 250Z') + B(244, 210, 16, 8, 2) + E(265, 204, 6.5, 8.5, -15) + E(265, 222, 6.5, 8.5, 15);
      s += E(150, 174, 28, 7);
      let b = P('M146 140L130 149Q126 156 133 157L149 159Z') + P('M144.5 136L145.5 166Q150 178 154.5 166L155.5 136Z');
      b += tutu(150, 140, 48, 20, 8) + tutu(150, 133, 34, 15, 6) + P('M139 100Q150 94 161 100L158 130H142Z');
      b += P('M140 101Q123 86 102 75Q95 80 101 86Q121 97 140 113Z') + P('M160 101Q177 86 198 75Q205 80 199 86Q179 97 160 113Z');
      b += C(150, 47, 11) + C(150, 82, 15) + P('M133 92Q130 64 150 64Q170 64 167 92Q164 80 158 78Q150 82 142 78Q136 80 133 92Z');
      b += P('M138 70Q138 60 143 63Q146 54 150 51Q154 54 157 63Q162 60 162 70Q150 66 138 70Z');
      b += eye(144.5, 87, 2.4) + eye(155.5, 87, 2.4) + smile(150, 93, 3.5);
      return s + tf(b, -18, -20.9, 1.12);
    };

    /* ---------- 2. reindeer ---------- */
    const tree = (x, y, h) => B(x - 6, y + h * .82, 12, h * .22) + Q([[x, y + h * .36], [x - h * .3, y + h * .86], [x + h * .3, y + h * .86]]) + Q([[x, y + h * .16], [x - h * .24, y + h * .6], [x + h * .24, y + h * .6]]) + Q([[x, y], [x - h * .17, y + h * .34], [x + h * .17, y + h * .34]]);
    const antler = m => { const X = x => m ? 300 - x : x, t = (a, b, c, d, w0, w1) => tube(X(a), b, X(c), d, w0, w1); return t(124, 86, 128, 56, 11, 9) + t(104, 66, 99, 34, 11, 9) + t(84, 52, 70, 24, 10, 8.5) + t(130, 98, 107, 104, 10, 9) + t(140, 112, 124, 86, 16, 13) + t(124, 86, 104, 66, 13, 12) + t(104, 66, 84, 52, 12, 11) + t(84, 52, 58, 44, 11, 9.5); };
    const reindeer = () => {
      let s = frame() + P('M154 18A18 18 0 1 0 154 50A20 20 0 0 1 154 18Z') + star(50, 96, 12) + star(250, 96, 12);
      s += [[26, 54], [276, 54], [88, 142], [212, 142], [84, 184], [216, 184]].map(p => C(p[0], p[1], 5.5)).join('');
      s += tree(42, 100, 110) + tree(258, 96, 116);
      s += P('M8 214Q70 196 140 216Q220 236 292 206V274Q292 292 274 292H26Q8 292 8 274Z') + P('M8 252Q90 234 170 254Q240 270 292 246V274Q292 292 274 292H26Q8 292 8 274Z');
      s += P('M114 160Q98 220 94 292H206Q202 220 186 160Z') + P('M126 236l6 -8l6 6l6 -8l6 6l6 -8l6 6l6 -8l6 8Q178 264 150 292Q122 264 126 236Z');
      s += bands([...qp(104, 174, 150, 200, 196, 174, 12), ...qp(198, 200, 150, 228, 102, 200, 12)], 0, 6);
      s += bands([[168, 213], [190, 209], [198, 266], [176, 270]], 90, 4) + ln('M179 270l-1 9M185 269v10M191 268l1 9M197 267l2 8') + E(180, 206, 11, 9);
      s += E(106, 122, 20, 9, -25) + E(107, 122, 12, 5, -25) + E(194, 122, 20, 9, 25) + E(193, 122, 12, 5, 25);
      s += antler(0) + antler(1) + E(150, 140, 34, 40) + E(150, 166, 22, 17) + E(150, 157, 10, 7.5) + C(126, 150, 6) + C(174, 150, 6);
      return s + eye(136, 134, 5) + eye(164, 134, 5) + smile(150, 171, 6);
    };

    /* ---------- 3. go-kart ---------- */
    const kart = (num, small) => {
      let s = small ? "" : tube(80, 190, 56, 184, 11, 10);
      s += B(70, 178, 36, 24, 5) + P('M114 170Q108 204 126 208H150L146 170Z') + P('M130 164Q126 196 140 208H178Q180 184 164 166Z');
      s += P('M122 204H202Q212 204 214 214L216 232H118Z') + P('M194 196Q238 190 262 214Q266 230 250 230H208Z');
      s += C(168, 218, 10) + ln(num ? 'M164 214q4 -5 8 0q0 4 -8 10h8' : 'M165 214l3 -3v14');
      s += tube(150, 178, 178, 182, 12, 11) + ln('M187 164q9 12 0 26M189 178l18 20');
      if (!small) s += C(181, 182, 7.5);
      s += C(150, 146, 24);
      if (!small) s += P('M126 140Q138 116 164 120L162 132Q144 128 134 146Z');
      s += P('M146 140Q148 132 162 132Q172 134 172 147Q171 160 158 162Q146 160 146 150Z') + eye(162, 145, 2.6) + smile(160, 153, 4);
      return s + C(100, 228, 26) + C(100, 228, 11) + C(232, 232, 22) + C(232, 232, 10);
    };
    const goKart = () => {
      let s = P('M8 96V26Q8 8 26 8H274Q292 8 292 26V96Z') + C(40, 40, 15) + cloud(66, 78, .55);
      for (let r = 0; r < 3; r++) for (let c = 0; c < 4; c++) { const fy = (x, y) => y + 5 * sin((268 - x) / 58 * PI), x0 = 210 + c * 14.5, x1 = x0 + 14.5, y0 = 26 + r * 14, y1 = y0 + 14; s += Q([[x0, fy(x0, y0)], [x1, fy(x1, y0)], [x1, fy(x1, y1)], [x0, fy(x0, y1)]]); }
      s += B(268, 22, 7, 82, 3) + C(271.5, 20, 5.5) + B(8, 96, 284, 20) + B(158, 80, 9, 24) + B(146, 18, 33, 68, 8) + rep(3, i => C(162.5, 33 + i * 19, 7.5));
      s += B(8, 116, 284, 142) + rep(9, i => B(8 + i * 284 / 9, 258, 284 / 9, 16)) + P('M8 274H292Q292 292 274 292H26Q8 292 8 274Z');
      s += ln('M20 214h40M10 228h44M34 242h30');
      s += tf(kart(1, 1), -22.7, 38.5, .62) + cloud(96, 252, .42) + cloud(110, 236, .3);
      return s + tf(kart(0, 0), 73.2, 52.8, .8);
    };

    /* ---------- 4. princess hairstyles ---------- */
    const bust = (cx, cy, sl) => P(`M${cx - 44} 278V${cy + 86}Q${cx - 44} ${cy + 56} ${cx - 18} ${cy + 52}H${cx + 18}Q${cx + 44} ${cy + 56} ${cx + 44} ${cy + 86}V278Q${cx + 44} 292 ${cx + 30} 292H${cx - 30}Q${cx - 44} 292 ${cx - 44} 278Z`) + P(`M${cx - 44} ${cy + 104}Q${cx} ${cy + 112} ${cx + 44} ${cy + 104}V${cy + 118}Q${cx} ${cy + 126} ${cx - 44} ${cy + 118}Z`) + (sl ? C(cx - 34, cy + 68, 13) + C(cx + 34, cy + 68, 13) : '') + P(`M${cx - 9} ${cy + 16}V${cy + 46}Q${cx - 16} ${cy + 50} ${cx - 24} ${cy + 54}Q${cx} ${cy + 84} ${cx + 24} ${cy + 54}Q${cx + 16} ${cy + 50} ${cx + 9} ${cy + 46}V${cy + 16}Z`);
    const face = (cx, cy) => C(cx, cy, 27) + C(cx - 16, cy + 12, 5.5) + C(cx + 16, cy + 12, 5.5) + eye(cx - 10, cy + 2, 3.8) + eye(cx + 10, cy + 2, 3.8) + ln(`M${cx - 13.6} ${cy + .8}l-3.2 -2M${cx + 13.6} ${cy + .8}l3.2 -2`) + smile(cx, cy + 12, 5.5);
    const tiara = (x, y, v) => P(`M${x - 18} ${y}Q${x - 19} ${y - 11} ${x - 11} ${y - 9}Q${x - 7} ${y - 20} ${x} ${y - 24}Q${x + 7} ${y - 20} ${x + 11} ${y - 9}Q${x + 19} ${y - 11} ${x + 18} ${y}Q${x} ${y - 6} ${x - 18} ${y}Z`) + (v === 0 ? C(x, y - 11, 5.5) : v === 1 ? heart(x, y - 11, 6.5) : Q(starP(x, y - 11, 9, 5.4, 5)));
    // scalloped edge along an ellipse (curly hair, frills)
    const scal = (cx, cy, rx, ry, a0, a1, n, k = .62) => { const p = arcP(cx, cy, rx, ry, a0, a1, n); let d = `M${n1(p[0][0])} ${n1(p[0][1])}`; for (let i = 1; i <= n; i++) { const c = n1(Math.hypot(p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1]) * k); d += `A${c} ${c} 0 0 1 ${n1(p[i][0])} ${n1(p[i][1])}`; } return d; };
    const swirl = (x, y) => ln(`M${x} ${y}a4 4 0 1 1 4 4a7 7 0 0 1 -8 -6`);
    const hairstyles = () => {
      let s = frame() + ln('M8 14Q150 46 292 14') + heart(64.8, 31, 7) + heart(150, 37, 7.5) + heart(235.2, 31, 7) + spk(24, 44, 6) + spk(276, 44, 6) + spk(108, 46, 5) + spk(192, 46, 5);
      // A: bun
      let x = 58, y = 118;
      s += bust(x, y, 1) + C(x, y - 50, 17) + P(`M${x - 30} ${y + 12}Q${x - 37} ${y - 39} ${x} ${y - 37}Q${x + 37} ${y - 39} ${x + 30} ${y + 12}Z`) + face(x, y);
      s += P(`M${x - 28} ${y}Q${x - 29} ${y - 32} ${x} ${y - 31}Q${x + 29} ${y - 32} ${x + 28} ${y}Q${x + 19} ${y - 18} ${x + 2} ${y - 19}Q${x - 15} ${y - 16} ${x - 28} ${y}Z`) + tiara(x, y - 25, 0);
      s += [.18, .39, .61, .82].map(t => C(x - 24 + 48 * t, y + 47 + 60 * t * (1 - t), 5.5)).join('');
      // B: braids
      x = 150; y = 106;
      s += bust(x, y, 0) + P(`M${x - 31} ${y + 24}Q${x - 38} ${y - 38} ${x} ${y - 37}Q${x + 38} ${y - 38} ${x + 31} ${y + 24}Z`);
      for (const m of [-1, 1]) { s += rep(4, i => E(x + m * (28 + i) + (i % 2 ? 2.5 : -2.5), y + 22 + i * 13, 10, 8, i % 2 ? 28 : -28)); const bx = x + m * 31, by = y + 68; s += P(`M${bx - 8} ${by}Q${bx} ${by + 22} ${bx + 8} ${by}Z`); }
      s += face(x, y) + P(`M${x} ${y - 29}Q${x - 30} ${y - 30} ${x - 28} ${y + 4}Q${x - 19} ${y - 15} ${x} ${y - 20}Z`) + P(`M${x} ${y - 29}Q${x + 30} ${y - 30} ${x + 28} ${y + 4}Q${x + 19} ${y - 15} ${x} ${y - 20}Z`);
      s += tiara(x, y - 26, 2) + ln(`M${x - 20} ${y + 52}Q${x} ${y + 66} ${x + 20} ${y + 52}`) + heart(x, y + 66, 6.5);
      // C: curls
      x = 242; y = 118;
      s += bust(x, y, 1) + P(scal(x, y - 4, 40, 40, 118, 422, 11) + `Q${x} ${y + 10} ${n1(x + 40 * cos(rad(118)))} ${n1(y - 4 + 40 * sin(rad(118)))}Z`);
      s += swirl(x - 34, y - 12) + swirl(x + 30, y - 12) + swirl(x - 30, y + 18) + swirl(x + 26, y + 18);
      s += face(x, y) + C(x - 15, y - 22, 10) + C(x + 15, y - 22, 10) + C(x, y - 27, 10.5) + tiara(x, y - 31, 1);
      s += P(`M${x} ${y + 60}L${x - 15} ${y + 51}Q${x - 19} ${y + 60} ${x - 15} ${y + 69}Z`) + P(`M${x} ${y + 60}L${x + 15} ${y + 51}Q${x + 19} ${y + 60} ${x + 15} ${y + 69}Z`) + C(x, y + 60, 5.5);
      return s;
    };

    /* ---------- 5. starship cockpit ---------- */
    const cockpit = () => {
      let s = frame() + Q([[18, 42], [84, 26], [72, 144], [18, 144]]) + Q([[96, 22], [204, 22], [218, 144], [82, 144]]) + Q([[282, 42], [216, 26], [228, 144], [282, 144]]);
      const cx = 150, cy = 82, A = -15, back = sector(cx, cy, 38, 9, 56, 17, 180, 360, 16);
      s += Q(rot(clip(back, 1, 0, cx - 18), cx, cy, A)) + Q(rot(clip(back, -1, 0, -(cx + 18)), cx, cy, A));
      s += bands(ell(cx, cy, 26, 26, 36), 75, [.3, .58]) + Q(rot(sector(cx, cy, 38, 9, 56, 17, 0, 180, 16), cx, cy, A));
      s += star(116, 42, 12) + star(188, 124, 12) + spk(112, 126, 5) + spk(186, 40, 5) + spk(130, 104, 3.5);
      s += C(44, 96, 20) + C(36, 90, 6) + C(52, 104, 5.5) + star(48, 56, 11) + spk(60, 128, 5);
      s += P('M232 96Q254 70 278 58Q266 86 244 104Z') + C(238, 101, 9) + star(242, 48, 11) + bands(ell(258, 128, 13, 13, 30), 70, [.5]) + spk(270, 92, 4);
      s += P('M8 168Q150 136 292 168V274Q292 292 274 292H26Q8 292 8 274Z') + P('M8 168Q150 136 292 168V180Q150 148 8 180Z');
      s += C(150, 206, 28) + C(150, 206, 21) + C(150, 206, 12) + C(150, 206, 5.5) + ln('M150 206l15 -14') + dot(140, 196, 2) + dot(160, 218, 2);
      s += B(24, 188, 76, 46, 8) + B(31, 195, 62, 32, 4) + ln('M37 214l8 -8l8 10l8 -12l8 8l8 -6l8 6');
      s += B(200, 188, 76, 46, 8) + B(207, 195, 62, 32, 4) + B(214, 207, 11, 15, 2) + B(232, 201, 11, 21, 2) + B(250, 211, 11, 11, 2);
      s += rep(4, i => C(30 + i * 18, 252, 7)) + rep(4, i => B(201 + i * 19, 245, 14, 14, 3));
      s += E(150, 272, 22, 8) + tube(150, 270, 150, 250, 12, 11) + C(150, 245, 10);
      return s + tube(118, 266, 110, 246, 8) + C(110, 242, 7) + tube(182, 266, 190, 246, 8) + C(190, 242, 7);
    };

    /* ---------- 6. pachycephalosaurus ---------- */
    const pachy = () => {
      let s = frame() + Q(starP(140, 44, 27, 19, 12)) + C(140, 44, 14);
      let d = 'M8 214'; for (let i = 0; i < 8; i++) d += 'q17.75 -28 35.5 0'; s += P(d + 'V242H8Z');
      s += tube(46, 240, 60, 112, 15, 11) + leaf2(60, 106, 14, 86, 10) + leaf2(60, 106, 104, 84, 10) + leaf2(60, 106, 22, 136, 9) + leaf2(60, 106, 100, 122, 9);
      s += P('M8 240Q150 230 292 240V274Q292 292 274 292H26Q8 292 8 274Z') + E(98, 278, 10, 6);
      // far leg, body, belly bands, back spots
      s += tube(198, 204, 200, 252, 15, 13) + P('M184 262Q182 250 196 250H210Q222 252 222 262Z');
      s += P('M16 150Q70 128 120 124Q164 120 200 98L236 116Q240 160 214 196Q186 226 140 222Q104 216 82 190Q56 168 16 150Z');
      s += bands([...qp(222, 124, 238, 160, 214, 196, 6), ...qp(214, 196, 186, 226, 146, 222, 6), ...qp(146, 222, 178, 204, 200, 174, 6), ...qp(200, 174, 214, 150, 216, 122, 6)], 125, [.25, .5, .7]);
      s += C(64, 146, 6.5) + C(94, 139, 8) + C(126, 136, 9) + C(158, 132, 8.5) + C(186, 118, 7.5);
      // near leg + arm
      s += P('M104 170Q96 214 124 230Q156 238 172 214Q182 188 168 168Q140 152 104 170Z') + tube(140, 226, 138, 252, 20, 17) + P('M112 266Q110 252 126 251H150Q168 252 168 266Z') + ln('M152 260v6M159 260v6');
      s += tube(222, 168, 236, 186, 11, 10) + C(238, 190, 7);
      // head: dome with knobs and spots, face
      s += P('M194 98Q188 52 226 48Q260 48 264 86Q230 78 194 98Z') + P('M194 98Q230 78 264 86Q280 94 278 110Q274 130 244 132Q206 132 194 98Z');
      s += C(194, 82, 6) + C(190, 96, 6) + C(197, 110, 6) + C(258, 84, 5.5) + C(270, 91, 5.5) + C(212, 66, 6.5) + C(230, 60, 6) + C(246, 69, 6) + C(226, 116, 6);
      return s + eye(236, 104, 4.5) + ln('M242 120q11 7 22 -3') + dot(270, 104, 1.6);
    };

    /* ---------- 7. shipwreck ---------- */
    const fish = (x, y, s, f) => { const X = v => x + f * v * s, Y = v => y + v * s; return Q([[X(-15), Y(0)], [X(-33), Y(-14)], [X(-30), Y(0)], [X(-33), Y(14)]]) + Q([[X(-14), Y(-7)], [X(-4), Y(-28)], [X(12), Y(-8)]]) + bands(ell(x, y, 19 * s, 13 * s, 30), 0, [.36, .62]) + eye(X(9), Y(-2), 2.8 * s) + smile(X(13.5), Y(4.5), 2.4 * s); };
