    /* ---------- 11. rooster ---------- */
    const feather = (bx, by, tx, ty, bend, w) => { const mx = (bx + tx) / 2, my = (by + ty) / 2, l = Math.hypot(tx - bx, ty - by), nx = -(ty - by) / l, ny = (tx - bx) / l, c = k => `${n1(mx + nx * k)} ${n1(my + ny * k)}`, a = `M${bx} ${by}Q${c(bend)} ${tx} ${ty}Q`, b = ` ${bx} ${by}Z`; return P(a + c(bend + w) + b) + P(a + c(bend - w) + b); };
